import { useNavigate } from 'react-router-dom';
import { Briefcase, GraduationCap, User, LogOut, ChevronRight } from 'lucide-react';
import { useAuth, ROLE_LABEL } from '../Auth';
import { Mod } from '../types';

const MODS: { key: Mod; label: string; Icon: typeof Briefcase }[] = [
  { key: 'kp', label: 'Kerja Praktek', Icon: Briefcase },
  { key: 'ta', label: 'Tugas Akhir', Icon: GraduationCap },
];

export function Modules() {
  const { user, mod, setMod, setRole, signOut } = useAuth();
  const nav = useNavigate();
  const cur = MODS.find((m) => m.key === mod);

  return (
    // h-dvh = tinggi layar sebenarnya (aman untuk address bar HP)
    <div
      className="h-dvh w-full flex items-center justify-center p-3 sm:p-6 lg:p-8 bg-cover bg-center bg-blue-100"
      style={{ backgroundImage: "url('/images/gedung.jpeg')" }}
    >
      {/* CARD UTAMA: menyesuaikan tinggi konten, maksimal setinggi layar */}
      <div className="w-full max-w-md sm:max-w-2xl lg:max-w-5xl 2xl:max-w-6xl max-h-full flex flex-col overflow-hidden rounded-2xl sm:rounded-3xl bg-white shadow-2xl">
        {/* HEADER */}
        <header className="shrink-0 bg-gradient-to-r from-blue-800 to-blue-700 text-white px-4 py-3 sm:px-6 sm:py-4 2xl:px-8 2xl:py-5 flex items-center gap-3 sm:gap-4">
          <div className="flex items-center gap-2 sm:gap-3 bg-white rounded-lg sm:rounded-xl px-2 py-1.5 sm:px-3 sm:py-2 shadow-md shrink-0">
            <img src="/images/logowidit.jpg" alt="Widyatama" className="h-7 sm:h-9 2xl:h-11 object-contain" />
            <div className="w-px h-6 sm:h-8 bg-slate-200" />
            <img src="/images/logoif.jpg" alt="IF" className="h-7 sm:h-9 2xl:h-11 object-contain" />
          </div>

          <div className="flex-1 min-w-0">
            <p className="text-[11px] sm:text-sm 2xl:text-base font-light leading-tight">
              Sistem Informasi Kerja Praktek &amp; Tugas Akhir
            </p>
            <p className="font-bold uppercase text-xs sm:text-base 2xl:text-lg leading-tight truncate">
              Teknik Informatika Universitas Widyatama
            </p>
          </div>

          <div className="flex items-center gap-2 text-sm shrink-0">
            <span className="hidden md:flex items-center gap-2 bg-blue-900/60 rounded-lg px-3 py-2">
              <User className="w-4 h-4 text-orange-300" />
              {user?.name.split(',')[0]}
            </span>
            <button
              onClick={signOut}
              aria-label="Keluar"
              className="flex items-center gap-2 bg-orange-500 hover:bg-orange-600 rounded-lg p-2 sm:px-3 font-medium transition"
            >
              <LogOut className="w-4 h-4" />
              <span className="hidden sm:inline">Keluar</span>
            </button>
          </div>
        </header>

        {/* BODY: hanya scroll kalau konten benar-benar tidak muat (fallback HP kecil) */}
        <div className="flex-1 min-h-0 overflow-y-auto grid lg:grid-cols-2 lg:overflow-visible">
          {/* KIRI: MODUL */}
          <section className="p-4 sm:p-6 lg:p-8 2xl:p-10">
            <h2 className="font-bold text-base sm:text-lg 2xl:text-xl text-blue-900 mb-3 sm:mb-4">
              Daftar Modul
            </h2>

            <div className="grid grid-cols-2 gap-3 sm:gap-4">
              {MODS.map(({ key, label, Icon }) => {
                const isActive = mod === key;
                return (
                  <button
                    key={key}
                    onClick={() => setMod(key)}
                    className={`group rounded-2xl border-2 p-3 sm:p-5 2xl:p-6 flex flex-col items-center gap-2 sm:gap-3 transition-all duration-200 ${
                      isActive
                        ? 'bg-gradient-to-br from-orange-50 to-blue-50 border-orange-500 shadow-lg shadow-orange-200/50 scale-[1.02]'
                        : 'bg-white border-slate-200 hover:border-blue-400 hover:shadow-md'
                    }`}
                  >
                    <div
                      className={`rounded-2xl p-2.5 sm:p-3 transition-colors ${
                        isActive
                          ? 'bg-gradient-to-br from-orange-500 to-orange-400 text-white'
                          : 'bg-blue-50 text-blue-700 group-hover:bg-blue-100'
                      }`}
                    >
                      <Icon className="w-6 h-6 sm:w-8 sm:h-8 2xl:w-10 2xl:h-10" />
                    </div>
                    <span
                      className={`font-semibold text-xs sm:text-sm 2xl:text-base text-center ${
                        isActive ? 'text-orange-700' : 'text-blue-900'
                      }`}
                    >
                      {label}
                    </span>
                  </button>
                );
              })}
            </div>
          </section>

          {/* KANAN: ROLE */}
          {cur && (
            <section className="p-4 sm:p-6 lg:p-8 2xl:p-10 bg-slate-50 border-t lg:border-t-0 lg:border-l border-slate-100">
              <h2 className="font-bold text-base sm:text-lg 2xl:text-xl text-blue-900 mb-3 sm:mb-4">
                Daftar Role
              </h2>

              <p className="text-xs sm:text-sm text-slate-500 mb-3 sm:mb-4 flex items-center gap-2">
                <span className="inline-block w-2 h-2 rounded-full bg-orange-500" />
                Modul: <span className="font-medium text-blue-800">{cur.label}</span>
              </p>

              <div className="space-y-2 sm:space-y-3">
                {user!.roles.map((r) => (
                  <button
                    key={r}
                    onClick={() => {
                      setRole(r);
                      nav('/app');
                    }}
                    className="group w-full text-left bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4 hover:border-orange-400 hover:shadow-md transition-all flex items-center justify-between"
                  >
                    <div className="min-w-0">
                      <p className="font-bold text-sm sm:text-base text-blue-800 group-hover:text-orange-600 transition-colors">
                        {ROLE_LABEL[r]}
                      </p>
                      <p className="text-xs text-slate-400 mt-0.5 truncate">
                        {user!.nim || user!.email}
                      </p>
                    </div>
                    <ChevronRight className="w-5 h-5 shrink-0 text-slate-300 group-hover:text-orange-500 group-hover:translate-x-0.5 transition-all" />
                  </button>
                ))}
              </div>
            </section>
          )}
        </div>

        <p className="shrink-0 text-center text-xs text-slate-400 py-2 sm:py-3 bg-white border-t border-slate-100">
          © Made with love in Informatika
        </p>
      </div>
    </div>
  );
}
